cd /testbed/tests && cat > queries/test_repro_tmp.py <<'EOF'
from django.test import TestCase
from queries.models import SingleObject, NullableName, Number, ReservedName

class T(TestCase):
    def test_meta_ordering_union(self):
        for i in range(1, 5):
            SingleObject.objects.create(name='n%d' % i)
        qs = SingleObject.objects.filter(pk__in=[1, 2]).union(SingleObject.objects.filter(pk__in=[3, 4]))
        print('sql:', qs.query)
        try:
            print('res:', list(qs))
        except Exception as e:
            print('FAIL:', type(e).__name__, e)
        print('derived:', qs.order_by().values_list('pk', flat=True).query)
        try:
            print('derived res:', list(qs.order_by().values_list('pk', flat=True)))
        except Exception as e:
            print('DERIVED FAIL:', type(e).__name__, e)
        try:
            print('second:', list(qs))
        except Exception as e:
            print('SECOND FAIL:', type(e).__name__, e)
EOF
python runtests.py queries.test_repro_tmp --settings=test_sqlite --parallel 1 2>&1 | tail -12
